module non_restoring_divider(
    input clk,
    input reset,
    input [15:0] dividend,
    input [15:0] divisor,
    output reg [15:0] quotient,
    output reg [15:0] remainder,
    output reg done
);
    reg [15:0] A; // A register for the dividend
    reg [15:0] Q; // Q register for the quotient
    reg [15:0] M; // M register for the divisor
    reg [4:0] count; // Count for division steps

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            A <= 0;
            Q <= 0;
            M <= 0;
            quotient <= 0;
            remainder <= 0;
            done <= 0;
            count <= 0;
        end else begin
            if (count == 0) begin
                A <= dividend;
                Q <= 0;
                M <= divisor;
                count <= 16; // Maximum 16 iterations for 16-bit numbers
                done <= 0;
            end else if (count > 0) begin
                // Shift left
                A <= {A[14:0], Q[15]};
                Q <= {Q[14:0], 1'b0};

                // Subtract M from A
                if (A >= M) begin
                    A <= A - M;
                    Q[0] <= 1; // Set LSB of Q
                end else begin
                    Q[0] <= 0; // Clear LSB of Q
                end

                count <= count - 1;
            end else if (count == 0) begin
                quotient <= Q;
                remainder <= A;
                done <= 1; // Indicate division is done
            end
        end
    end
endmodule

