module butterworth_filter (  
    input clk,  
    input rst,  
    input in_signal,  
    output reg out_signal  
);  
    // Filter coefficients for a 2nd order Butterworth filter (example values)  
    parameter a0 = 3'b001;  
    parameter a1 = 3'b010;  
    parameter a2 = 3'b001;  
    parameter b1 = 3'b001;  
    parameter b2 = 3'b000;  
    reg [1:0] state;  
    reg [1:0] prev_signal;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= 2'b00;  
            prev_signal <= 2'b00;  
            out_signal <= 1'b0;  
        end else begin  
            // State machine for filter operation  
            state <= {state[0], in_signal};  
            // Filter calculation  
            out_signal <= (a0 * state[1] + a1 * state[0] + a2 * in_signal) >> 2;  
            prev_signal <= state;  
        end  
    end  
endmodule

