module deserializer_32bit (  
    input wire clk,  
    input wire reset,  
    input wire [31:0] serialized_in,  
    output reg bit_out  
);  
    reg [4:0] index; // 5 bits to count from 0 to 31  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            index <= 0;  
            bit_out <= 0;  
        end else begin  
            if (index < 32) begin  
                bit_out <= serialized_in[index];  
                index <= index + 1;  
            end  
        end  
    end  
endmodule

