module pipelined_adder (
    input clk,
    input rst,
    input [7:0] a, // First operand
    input [7:0] b, // Second operand
    output reg [7:0] result // Result of addition
);
    // Stage registers
    reg [7:0] a_reg, b_reg;
    reg [7:0] exec_result;

    // Pipeline stages
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            a_reg <= 8'b0;
            b_reg <= 8'b0;
            exec_result <= 8'b0;
            result <= 8'b0;
        end else begin
            // IF Stage
            a_reg <= a;
            b_reg <= b;

            // ID Stage (no operation, just passing values)
            // EX Stage
            exec_result <= a_reg + b_reg;

            // MEM Stage (no operation, just passing value)
            // WB Stage
            result <= exec_result;
        end
    end
endmodule

