module SRT_Divider (  
    input [15:0] numerator,  
    input [15:0] denominator,  
    input start,  
    input clk,  
    input rst,  
    output reg [15:0] quotient,  
    output reg [15:0] remainder,  
    output reg done  
);  
    reg [15:0] temp_numerator;  
    reg [15:0] temp_denominator;  
    reg [3:0] count;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            quotient <= 16'b0;  
            remainder <= 16'b0;  
            temp_numerator <= 16'b0;  
            temp_denominator <= 16'b0;  
            count <= 4'b0;  
            done <= 1'b0;  
        end else if (start) begin  
            if (denominator == 0) begin  
                quotient <= 16'hFFFF; // Handle division by zero  
                remainder <= numerator;  
                done <= 1'b1;  
            end else if (count < 16) begin  
                // Perform SRT division steps (simple version)  
                temp_numerator <= {remainder, 1'b0};  
                if (temp_numerator >= (temp_denominator << 1)) begin  
                    temp_numerator <= temp_numerator - (temp_denominator << 1);  
                    quotient <= (quotient << 1) | 1;  
                end else begin  
                    quotient <= quotient << 1;  
                end  
                count <= count + 1;  
            end else begin  
                remainder <= temp_numerator;  
                done <= 1'b1;  
            end  
        end  
    end  
endmodule

