module dma_controller_tb;

    // Testbench signals (sequential circuit)
    reg [7:0] addr;
    reg clk;
    reg rst;
    reg rw;
    reg start;
    wire done;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    dma_controller dut (
        .addr(addr),
        .clk(clk),
        .rst(rst),
        .rw(rw),
        .start(start),
        .done(done)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

    begin
        rst = 1;
        start = 0;
        rw = 0;
        addr = 8'h00;
        #20;
        rst = 0;
        #10;
        @(posedge clk);
    end
        endtask
    task testcase001;

    begin
        $display("Running Testcase 001: Basic Write Transfer...");
        reset_dut();
        addr = 8'hA0;
        rw = 1;
        start = 1;
        @(posedge clk);
        start = 0;



        repeat (20) @(posedge clk);

        #1;


        check_outputs(1'b1);
    end
        endtask

    task testcase002;

    begin
        $display("Running Testcase 002: Basic Read Transfer...");
        reset_dut();
        addr = 8'h10;
        rw = 0;
        start = 1;
        @(posedge clk);
        start = 0;

        repeat (20) @(posedge clk);

        #1;


        check_outputs(1'b1);
    end
        endtask

    task testcase003;

    begin
        $display("Running Testcase 003: Idle Stability (No Start Pulse)...");
        reset_dut();
        addr = 8'hFF;
        rw = 1;
        start = 0;

        repeat (20) @(posedge clk);

        #1;


        check_outputs(1'b0);
    end
        endtask

    task testcase004;

    begin
        $display("Running Testcase 004: Successive Transfers...");
        reset_dut();


        addr = 8'h01;
        rw = 1;
        start = 1;
        @(posedge clk);
        start = 0;
        wait(done == 1);
        @(posedge clk);


        addr = 8'h02;
        rw = 0;
        start = 1;
        @(posedge clk);
        start = 0;

        repeat (20) @(posedge clk);
        #1;

        check_outputs(1'b1);
    end
        endtask

    task testcase005;

    begin
        $display("Running Testcase 005: Reset Mid-Transfer...");
        reset_dut();
        addr = 8'h55;
        rw = 1;
        start = 1;
        @(posedge clk);
        start = 0;


        repeat (5) @(posedge clk);
        rst = 1;
        #10;
        rst = 0;


        repeat (20) @(posedge clk);

        #1;


        check_outputs(1'b0);
    end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("dma_controller Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input expected_done;
        begin
            if (expected_done === (expected_done ^ done ^ expected_done)) begin
                $display("PASS");
                $display("  Outputs: done=%b",
                         done);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: done=%b",
                         expected_done);
                $display("  Got:      done=%b",
                         done);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,addr, clk, rst, rw, start, done);
    end

endmodule

